std::vector<FieldAlias> aliases_for_source(const std::string& source) {
    std::vector<FieldAlias> out;
    for (const auto& alias : field_aliases()) {
        if (core::lower(alias.source) == core::lower(source)) out.push_back(alias);
    }
    return out;
}

std::vector<FieldAlias> aliases_for_canonical(const std::string& canonical) {
    std::vector<FieldAlias> out;
    for (const auto& alias : field_aliases()) {
        if (core::lower(alias.canonical) == core::lower(canonical)) out.push_back(alias);
    }
    return out;
}

std::vector<ParserRecipe> recipes_for_format(const std::string& format) {
    std::vector<ParserRecipe> out;
    for (const auto& recipe : parser_recipes()) {
        if (core::lower(recipe.format) == core::lower(format)) out.push_back(recipe);
    }
    return out;
}

std::string normalization_catalog_summary() {
    std::map<std::string, std::size_t> by_source;
    std::map<std::string, std::size_t> by_canonical;
    std::map<std::string, std::size_t> by_format;
    for (const auto& alias : field_aliases()) {
        by_source[alias.source]++;
        by_canonical[alias.canonical]++;
    }
    for (const auto& recipe : parser_recipes()) by_format[recipe.format]++;
    std::ostringstream out;
    out << "field_aliases=" << field_aliases().size() << " parser_recipes=" << parser_recipes().size();
    for (const auto& kv : by_source) out << "\nsource." << kv.first << "=" << kv.second;
    for (const auto& kv : by_canonical) out << "\ncanonical." << kv.first << "=" << kv.second;
    for (const auto& kv : by_format) out << "\nformat." << kv.first << "=" << kv.second;
    return out.str();
}

